// Fallback images for Japanese cards: many have an image on TCGdex's CDN that the TCGdex API doesn't list
// (tcgdex/cards-database#2477). The list is generated by scripts/gen-ja-cdn-images.mjs (re-run it from time
// to time; drop this once TCGdex fixes the issue). Same host and URL shape as API images, so nothing changes
// downstream: cardImage(base, "low" | "high") appends "/low.webp".
import { JA_CDN_IMAGES } from "./ja-cdn-images.data";

const CDN = "https://assets.tcgdex.net/ja";

let expanded: Map<string, { serie: string; ids: Set<string> }> | null = null;

/** "001-003,010" -> {"001","002","003","010"} (runs keep their zero padding). */
export function expandIds(spec: string): Set<string> {
  const out = new Set<string>();
  for (const part of spec.split(",").filter(Boolean)) {
    const m = /^(\d+)-(\d+)$/.exec(part);
    if (!m) {
      out.add(part);
      continue;
    }
    const width = m[1].length;
    for (let n = Number(m[1]); n <= Number(m[2]); n++) out.add(String(n).padStart(width, "0"));
  }
  return out;
}

function table() {
  if (!expanded) {
    expanded = new Map();
    for (const [setId, { s, ids }] of Object.entries(JA_CDN_IMAGES)) expanded.set(setId, { serie: s, ids: expandIds(ids) });
  }
  return expanded;
}

/** CDN image base for a Japanese card the API lists without an image, or undefined. Raw (unprefixed) ids. */
export function jaCdnImage(rawSetId: string, localId: string): string | undefined {
  const hit = table().get(rawSetId);
  if (!hit || !hit.ids.has(localId)) return undefined;
  return `${CDN}/${hit.serie}/${rawSetId}/${encodeURIComponent(localId)}`;
}
